INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p989318-ise205', 'stk-user5812', 'ISE 205', 'info', '{"desc": "جودة المقرر بشكل عام :\n\nالكتاب من أفضل الكتب الموجودة اللي درستها في الجامعة\n\nالمواضيع التي يغطيها المقرر :\n\nالإحتمالات … الإحصاء بشكل عام … والسنترال لمت ثيوروم … الخ\n\nالكتاب المستخدم للمقرر :\n\nApplied Statistics and Probability for Engineers\nauthors :\nDouglas C. Montgomery\nGeorge C. Runger\n\nالأسئلة والأمثلة المستخدمة في المقرر :\n\nالأمثلة ممتازة … والأسئلة متنوعة وشاملة … وأغلبها من الحياة الصناعية … يعني أغلب الأمثلة تتكلم عن المصانع وكذا … فيعتبر تطبيق مباشر عالوظيفة .\n\nمدى فائدته في الناحية التطبيقية :\n\nما طبقت في شركة لسه فما أعرف :d", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-205-engineering-probability-and-statistics/120934/2", "user": "user5812", "ts": 1329653552000, "tid": 120934, "pn": 2}}', 1329653552000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1027361-ise205', 'stk-a_s_m', 'ISE 205', 'info', '{"desc": "مادة جميلة وتتكلم عن الاحتمالات والاحصاء بشكل عام\nمهمة جدا في تخصص الاندستريال لانها تعتبر قلب التخصص واساس المواد والطرق لحل المشاكل المختلفة\nكتابها رائع بكل ماتعنيه الكلمة من معنى\nوالمادة اصعب مافيها بالنسبة لي كان تشابتر 2 (الاحتمالات)\nالباقي مع حل المسائل والتدريب تصير المادة سهالات.\nافهم قبل لاتدور القريد ! (مع انك ماتجيب قريد الا وانت فاهم ان شاءالله)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-205-engineering-probability-and-statistics/120934/3", "user": "A_S_M", "ts": 1335197981000, "tid": 120934, "pn": 3}}', 1335197981000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1052544-ise205', 'stk-user3193', 'ISE 205', 'info', '{"desc": "تعتبر هذه المادة اهم مادة في ISE وهي حجر الاساس للتخصص واي كورس راح تدرسه لازم يمر عليك شي من الي درسته بالـ 205\nالمادة هذي راح تدرس فيها التالي:\n\nProbability (الاحتمالات)\n\nمثال 1:\n\nعندك العملة المعدنية (الهلل) له وجهين الوجه الاول (السيفين والنخلة) و الوجه الثاني (قيمة الهلل) لو انك رميتها على الارض كم احتمال ان الوجه المكشوف يكون سيفين ونخلة ؟ بالتأكيد 50% لان القطعة المعدنية لا يوجد لها الا وجهين فقط لذلك تساوت الاحتمالات (احتمال ان يكون الوجه سيفين ونخله هو نفس احتمال ان الوجه يكون قيمة الهلل وكل الاحتماليين = 50%)\n\nتذكر دائما مجموع الاحتمالات يكون 100%\n\nماذا يعني احتمال ان يكون الوجه المكشوف للسيفين والنخلة هو 50 % ؟\n\nمعناه انه لو رمينا القطعة المعدنية على الارض مرتين راح ينكشف في الرمية الاولى الوجه الاول وراح يكنشف في المرة الثانية الوجه الثاني يعني اما ينكشف المره الاولى السيفين والنخلة والمرة الثانية قيمة الهلل او ان ينكشف المره الاولى قيمة الهلل والمره الثانية السيفين والنخلة او بشكل عام لو نرمي القطعة المدنية 10 مرات سوف نحصل 5 مرات سيفين ونخلة ولو رميناها 40 مره سوف نحصل 20 مره سيفين ونخلة\n\nالكلام المكتوب اعلاه هو صحيح بشكل نظري فقط لانه قد تجرب انت العملية وتحصل على احتمال غير الموجود اعلاه مثلا رميت القطعة المعدنية مرتين وحصلت في كل مره على السيفين والنخلة وهذا معناه ان الاحتمال الي حصلت عليه انت بهذه التجربه هو 100% للسيفين والنخلة و 0% لقيمة الهلل وكل ما زدت في عدد التجارب كل ماقربت للاحتمال الصحيح (النظري)\n\nولكن ماذا لو جربت العملية اكثر من 100 مليون مرة ؟\nراح تجد ان الاحتمالات المذكورة بالاعلى هي صحيحة ومطابقة للتجربة\n\nتذكر كل مازدت في عدد التجارب راح تكون قريب من الاحتمال الصحيح\n\nايضا راح تدرس شي اسمه Probability Distrubation وهي مهمة جدا ولو بشرحها يبي لي يومين\n\nايضا راح تدرس estimation of parameters وهي مهمة جدا ايضا وراح تدرس فيها مثلا كيف تحسب الافرج (معروف اكيد) لدرجات 40 طالب عندك والمود والستاندر دفيشين والفايرينس وكلها حاجات سهلة ولها معنى وتفيدك في تحليل ودراسة الدرجات او الداتا الي انت تملكها\n\nالكورس باختصار هو لب التخصص ويجب ولازم والمفروض انك تكون فاهمه 100% عشان تمشي مضبوط ان شاء الله في باقي المواد\n\nالكورس ليس صعب جدا ولكن يحتاج لمذاكرة اول باول حتى لا تضيع المعلومات من راسك لان المعلومات الجديدة فيه كثيرة وكلها مهمة جدا ولا تخاف ترى اغلبها سهل\n\nالكتاب المستخدم جدا رائع ولذيذ ايضا للقراءة\n🤠 - وانصح كل اندسترالي ان يقرا هذا الكتاب كاملا مكملا 🙂\n\nصعوبة الكورس: 8 من 10\n\nتحياتي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-205-engineering-probability-and-statistics/120934/4", "user": "user3193", "ts": 1339138827000, "tid": 120934, "pn": 4}}', 1339138827000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1306083-ise205', 'stk-kemooo', 'ISE 205', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nاخذت الكورس هذا مع الدكتور دفوعه … وكان بمثابه اب لنا, والله اني احترمه كثير رغم انه كبر بالسن الحين وسار يغلط خفيف بس ماشاء الله عليه شارب الماده شرب\n\nالمهم\n\n205 وما ادراك ما 205 … الماده هذي يا سيدي تحتاج فيها 3 حاجات\n\n1- تقرا الكتاب\n\n2- تحل اسئلته كامله\n\n3- تلخص القوانين\n\nوانتا كدا امورك في السليم…\n\nالماده جدا جدا سهله ماعدا شابتر 2 فركزو فيه كويس لانه يوجع الراس 🙂 … اذا فهمت شابتر 2 انتا ضمنت 20% من الكورس في جيبك … ايش القريد اللي تقدر تطلع فيه وانتا شاد حيلك وكويزاتك تمام ومزبط شابتر 2 … A او B+ … اذا ما شديت حيلك مرا C+ او C واذا اهملت الماده حتنزل تحت … الماده سهله وحرام تضييعها, بالنسبه لي ميجر 1 هو اصعب واحد بسبب شابتر 2 …\n\nايش الاغلاط اللي اخطيت فيها انا في الماده وقللت من درجاتي …\n\nدكتور دفوعه كان يعطينا كويزات في اوقات شوي غلط يكون في مياجر ولا توك مخلص من مياجر ومالك نفس تذاكر … بس هذا ما كان عذر لذلك درجاتي في الكويزات ماكانت طيبه\n\nشي كان يتعبني وانا احل الهوموركات انه المانيول سليوشن مليان اخطاء فتشك في اجابتك وهيا صح …\n\nالاشياء اللي ساعدتني في الماده\n\nالـ Help session حق الماده والـ old exams … شييكو kfupmresources للفايده\n\nبالنسبه للي يسأل ويقول لازم احل اسئله الكتاب كلها … في اسئله كثير مكرره فحتقدر تعملها Skip او تحله في مخك وخلاص السوال اللي تشوف فكرته جديده حله … كل ما اتمرنت زياده كل ما تحس انك فهمت احسن واتمكنت من الماده … بالنسبه لي فهمت الماده من اسئله الكتاب …\n\nبالنسبه للاسئله اللي فيها اخطاء انا محددها كلها في كتابي بس باقي اكتبها وان شاء الله في ردي الجاي اكتبها …\n\nومحدد كمان في كتابي الاسئله المهمه لكل شابتر بحيث انه اذا كنت مضغوط وتبغا الزبد تشييك ع الاسئله هذي وان شاء الله تكون كافيه … بس الافضل لو راجعت جميع الاسئله لانه قدره استيعاب شخص لشخص تختلف …\n\nايوا في شي مهم كمان !!!\n\nاستغل الساعات المكتبيه كثير تفيد جداً, ولا تضيع اي Help session للدكتور دفوعه …\n\nان شاء الله لي رجعه اكتب فيها الاسئله … ولو نسيت بالله احد يرسلي مسج خخخخخخ\n\nبـــر بـــ 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-205-engineering-probability-and-statistics/120934/5", "user": "KeMoOo", "ts": 1387225064000, "tid": 120934, "pn": 5}}', 1387225064000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1403961-ise205', 'stk-user2352', 'ISE 205', 'info', '{"desc": "هذا الكورس مثل ما هو معروف فهمه هو مفتاح التفوق في تخصص الهندسة الصناعية،،\nوهذا الكتاب ممتاز في شرح الكونسبت في حالة إنك ما فهمت من الكتاب المقرر\nhttps://www.dropbox.com/s/a8d7q2vpg0hid16/Schaum''s%20Outline%20of%20Probability%20and%20Statistics%2C%20Third%20Edition%202009.pdf?dl=0\nوأنصح طلاب الكورس جميعاً بالرجوع إلى هذه المحاضرات المسجلة من لنفس كتاب الكورس فيها حلول مسائل مهمة ومفيدة وتوضيح للكونسبت\nملفات الفيديو هنا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-205-engineering-probability-and-statistics/120934/10", "user": "user2352", "ts": 1412439824000, "tid": 120934, "pn": 10}}', 1412439824000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1422980-ise205', 'stk-user8581', 'ISE 205', 'info', '{"desc": ":: بشكل عام اشوفه كورس سهل لكن لا تنخدع وتسحب على المادة لأنك راح تجيب العيد .\n:: الكتاب جيد وحاول تحل الامثلة وبعهدا تروح للاسئلة .\nالكورس يعادل stat 319 والكتاب نفسه للكورسين\n…\n- بعد كل شابتر حل 4 او 5 اسئلة مستواها بين الصعب والمتوسط من كل سكشن عشان تتأكد انك فاهم .\n- الشابتر الثاني فهمه صح لأنه تقريبا اصعب شابتر .\n- فيه قوانين كثيرة سو ملخص لها او على الاقل حمل الفورملا شيت للمياجر من السمسترات الماضي وانت تحل اسئلة الكتاب او الاولداقزام حاول تستخدمها وتعرف كل قانون متى تستخدمه.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-205-engineering-probability-and-statistics/120934/12", "user": "user8581", "ts": 1437934978000, "tid": 120934, "pn": 12}}', 1437934978000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1450442-ise205', 'stk-fahad_2012', 'ISE 205', 'info', '{"desc": "واحد من اهم الكورسات في التخصص ويدخل في الكثير منها\nالى اخر كورس تاخذه في التخصص ممكن تستخدم بعض الاشياء الي اخذتها من الـ 205\n\nجودة المقرر بشكل عام : فوق الممتاز\n\nالمواضيع التي يغطيها المقرر : الاحتمالات , random distribution , discrete and continous variables …\n\nالكتاب المستخدم للمقرر : من افضل كتب التخصص\n\nالأسئلة والأمثلة المستخدمة في المقرر : متنوعة وكثيرة وممتازة\n\nمدى فائدته في الناحية التطبيقية : الكورس راح تستفيد منه في الناحية التطبيقية بشكل غير مباشر\nعلى سبيل المثال كورس الـ 405 مفيد وتطبيقاته كثيره ومفاهيم كثيرة من هالكورس تعتمد بشكل كبير على الـ 205\n\nالكتاب راح تستخدمه في 325 للمعلومية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-205-engineering-probability-and-statistics/120934/16", "user": "Fahad_2012", "ts": 1464242238000, "tid": 120934, "pn": 16}}', 1464242238000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1537219-ise205', 'stk-user12137', 'ISE 205', 'info', '{"desc": "T231\n\nجودة المقرر بشكل عام : ممتاز ومتسلسل بشكل جيد ومرتب\n\nالمواضيع التي يغطيها المقرر : الاحصاء التطبيقي للمهندسين (بازيد على الكلام مستقبلا بإذن الله)\n\nالكتاب المستخدم للمقرر : الكتاب عليه مدح قوي بس للأسف ما قريته واجد بس شوي وكان سهل الهضم ماتع\n\nالأسئلة والأمثلة المستخدمة في المقرر : متنوعة وكثيرة وممتازة ومن أرض الواقع\n\nمدى فائدته في الناحية التطبيقية : ما عندي علم\n\nطريقة مذاكرتي:\n-أركز مع الدكتور في الكلاس (عطية) قدر الامكان\n-أصور سبورته وأقرأها\n-اقرا السلايدات\n-أشوف فيديوهاته قبل المياجر\n-أحل الهوموورك بنفسي واراجع منها\n-أحل ملف المراجعة من الدكتور واشوف هيلب سشنه\n-أحل اولد اكزام من نيبولا\nوجبت B+\n\nأخطاء ارتكبتها:\n-الخطأ الاكبر هو أني لم أذاكر بشكل يومي او مستمر وأني ما نظمت وقتي بشكل جيد قبل المياجر فصارت مذاكرتي سبيد رن بدون ما آخذ راحتي في كل خطوة\n-غبت أيام وتراكمت علي الدروس وأنكبت (المادة تحتاج متابعة مستمرة)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-205-engineering-probability-and-statistics/120934/21", "user": "user12137", "ts": 1704979565000, "tid": 120934, "pn": 21}}', 1704979565000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p849889-ise205', 'stk-fond_of_you', 'ISE 205', 'info', '{"desc": "ما عندي له فياينلات بس شد حيلك الفاينل سلخ شوي …\n\nبس كويس انا سمعت انه معاكم ضرغام فما راح يسلخكم كثير لكن شوي 😛\n\nبس اتذكر جاب اسئلة قريبة من اسئلة الكتاب … فا اتذكر جاب بروف حق سوال 7.20 …\n\nوجاب سوال قريب من 7.15 وحل 7.18 عشان تظمئن بس …\n\nوجاب اسئلة من شكشن 7.4 ما ادري اذا هو معك او لا …\n\nاللي جابه صراحة ما اتذكر بالضبط بس\n\nهو اكسمبل محلول بالكتاب حل انت من 7.7 الى 7.10…\n\nوجاب تعاريف غالبيتها من Ch7 … فركز عليه الشبتر مهم جدا وبن داية يعتبره من اهم الشابتر …\n\nبس برضه ترى جاب اسئلة على ch 8 و ch 4 و ch 3 …\n\nما كان معنا Ch 2+6 …\n\nيعني الاختبار كان طويل جدا … بس ممكن يغير عشان كومن وكذا …\n\nلكن اسئلته من شرحه بس شوية تركيز يبغى لك … موفق واسف اطلت عليك 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise205/108034/8", "user": "Fond_Of_You", "ts": 1307697808000, "tid": 108034, "pn": 8}}', 1307697808000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p958507-ise205', 'stk-user6452', 'ISE 205', 'info', '{"desc": "من قروب الهندسه الصناعيه على الفيس بوك\n\nطلاب الدكتور شكري 205 ise\nانا اليوم رحت وسالت الدكتور على المنهج وقال المنهج كالتالي\n\n( النسخة الخامسة من الكتاب) :\n\n… Ch 4 ) 4.1 to 4.8\n\nch 7 ) 7.1 to 7.3\n\nch 8 ) 8.1 to 8.5\n\nch 10\n\n10.1.3 - 10.2.3 -10.3.3 - 10.4 ( confidence interval for u ) -10.5.1 and 10.4\n\nلكن ترا فيه احتماليه ان الاختبار ما يكون كومن\nبالتوفيق 🌹 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-205/117449/2", "user": "user6452", "ts": 1325614516000, "tid": 117449, "pn": 2}}', 1325614516000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p860087-ise205', 'stk-user2179', 'ISE 205', 'info', '{"desc": ". .\n\nياهلا والله بابوعبدالله\n\n👍\n\nكان قلت لي من بدري عشان اتأخر عشانك 🥰\n\nحياك الله في قسم السستم وانشالله يكون الخير في اختيارك ❤️\n\nالـ 205 مستواها سهل الى متوسط ، ما اشوف فيها اي صعوبه ، لكنها مهمه جدا\n\nلانك راح تستخدم الاشياء اللي بتتعلمه فيها كثيرا في التخصص من قوانين ونظريات\n\nالماده احصاء تقدر تعتبرها رياضيات واشوفها اسهل من الرياضيات وكتابها من احسن كتب التخصص\n\nسهل الفهم ، يشرح لك بعدين يعطيك القانون وبعدها مثال ، ، وفيه اسئله تقدر تحلها واجابات الفرديه موجوده\n\nبنفس الكتاب ، او اكيد الشباب معاكم بيوفرون لكم المسلوشن مانيوال …\n\nبالنسبه للنوت … نوت الدرويش كويس … وما ادري اذا فيه احد من الدكاتره غيره يكتب او لا …\n\nطبعا النصايح العامه … اولا … لا تفوت اي شي منها بدون ماتفهمه لانك بتوفر على نفسك كثير بعدين\n\nلانه في بعض المواد بعدين في التخصص يكون او شابتر او شابترين من الـ 205 وما يشرحه الدكتور\n\nويقول راجعوا الـ 205 لحالكم …\n\nثانيا … زي ماقلت لك الماده متوسطه الى سهله ومافيه صعوبه مره ، خاصه اذا كنت تحل تمارين كثير عليها\n\nعشان تتعود ، لانه من النوع السهل الممتنع …\n\nانشالله اكون افدتك والشباب مايقصرون معك باذن الله\n\nتحياتي\n\n🌹\n\n. .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-205/109095/2", "user": "user2179", "ts": 1309181908000, "tid": 109095, "pn": 2}}', 1309181908000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p374198-ise205', 'stk-waleed_2005', 'ISE 205', 'srcP', '{"html": "تفضل يالغالي 🙂<br><br>​<span data-fid=\"stk-f374198-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f374198-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f374198-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f374198-0": {"name": "se1.pdf", "v": "data:application/pdf;base64,"}, "stk-f374198-1": {"name": "se2.pdf", "v": "data:application/pdf;base64,"}, "stk-f374198-2": {"name": "se3.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-205/70967/2", "user": "waleed_2005", "ts": 1235819421000, "tid": 70967, "pn": 2}}', 1235819421000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p959360-ise205', 'stk-user8681', 'ISE 205', 'srcP', '{"html": "هذي الهومووركات اللي كان يطلبها منا 🙂<br><br>​<span data-fid=\"stk-f959360-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f959360-0": {"name": "4_-_Homework_And_Lab_Excercises_Homeworks.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-205/117449/7", "user": "user8681", "ts": 1325746559000, "tid": 117449, "pn": 7}}', 1325746559000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dark_prince-ise205', 'stk-dark_prince', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f98290", "n": "Dr. Mohammad Al-Haboubi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 205\n\nTerm : 112\n\n----------------------------------\n\nالدكتور محمد الحبوبي من اكثر الناس خبرة و علم في القسم\n\nواضح ان الرجل فاهم و اعتقد انه مسؤول عن جزء من التوسعة في الحرم\n\nبصراحة الدكتور طيب و اخلاق … لكن عنده عادة غريبة انه ما يسمح لاي احد يدخل بعد ما يبدا الكلام\n\nفمن الآن اللي دائما يتأخر عن الكلاس 4 او 5 دقائق نصيحة لا تنزل عنده\n\nالدكتور متشدد في التحضير و يحفظ اسماء الطلاب واشكالهم من ثاني اسبوع ( ما شاء الله )\n\nبالنسبة للاختبارات فاختباراته كانت متفاوتة في الصعوبة\n\nكان عندنا 5 اختبارات كل اختبار عليه 12 درجة وكان واحد صعب والثاني سهل والثالث صعب والرابع سهل والخامس صعب…تقريبا شيء زي كذا\n\nبشكل عام المدرس يخنبر فهم الطالب مو مذاكرته\n\nيعني لو تذاكر كل الكتاب و تحل كل الاكسرسايز وانت مو فاهم 100% راح تحصل اسئلة غريبة عجيبة تقيس فهمك للكونسبت … واللي طبعا ما راح تحصلها في الكتاب نهائيا !!\n\nنصيحة مني اذا بتنزل عنده خذ لك نوت واكتب معاه في الكلاس كل كلمة و لا تخلي شيء يمر وانت مو فاهم لانه تأكد انه كل حرف يقوله راح تحصله في الاختبار\n\nبشكل عام اذا كنت من النوع اللي يفهم مع المدرس و يركز معاه فراح ترتاح مع المدرس كثير و تجيب قريد عالي\n\nاما اذا كنت من نوع الـSelf Study فدور لك مدرس ثاني احسن لك لانك راح تتعب كثير معاه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1049183-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-al-haboubi/98290/17", "user": "Dark_Prince", "ts": 1338593882000, "tid": 98290, "pn": 17}}]}', 1338593882000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_ali_20-ise205', 'stk-abu_ali_20', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f98290", "n": "Dr. Mohammad Al-Haboubi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE205\nالتحضير : دائما يحضر , وراح يحفظ أسماء الطلاب غالبا بعد فترة.\n\nطريقة الشرح : شرح روعة تفهم كل شي يقوله بأسهل الطرق وأحسن الأمثلة.\n\nالكويزات : كان ماعندنا كوزات.\n\nالمياجر: ( خمس اختبارات ) بعد ما ننتهي من كل شابتر ناخد Test عليه .\nوكانت أسألته على قد شرحه , اعرف ان أي شي يشرحه احتمال كبير راح يجيك في الاختبار.\n\nالفاينلات : كان صعب شوية ولكن مو مستحيل يختبر الفهم وليس الحفظ.\n\nالقريد النهائي: أعطيه +A أكيد.\n\nالصوت: وااااضح جدا\n\nإضافات:\nبالنسبة لي أحسن دكتور في القسم مر علي الى الآن، شرح على مستوى وتصحيحه بالملي ( يعطيك حقك وبس), والقريد العالي عنده مو مستحيل، اذا كانت أجوبته مثل مايبي هو …\nدائما يحب التفصيل في الاجابات ،\nأنا من بداية الترم كنت أكتب كل كلمة يكتبها على السبورة ، وأكتب كل كلمة يكررها في الكلاس ويقول انها مهمة.\nأي شيئ يكتبه على السبورة دائما مهم وممكن يجي في الاختبار .\nبالنسبة لي كنت أذاكر من سلايداته، والنوت الي اكتبها معاه، اذا في شي مافهمته أقرأ الكتاب، واحيانا أحل بعض الأسئلة من الكتاب،\n(خصوصا شابتر 2 أسئلة الكتااااب مهمة جدااا)\nفي النهاية طلعت بقريد ما كنت أحلم به طوووووول عمري ولله الحمد …\nما أقول الا شكرا دكتور محمد 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1433180-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-al-haboubi/98290/28", "user": "ABU_ALI_20", "ts": 1447412430000, "tid": 98290, "pn": 28}}]}', 1447412430000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mkd-ise205', 'stk-mkd', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f98636", "n": "Dr. Omar Al-Turki", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "خذت معه ISE 205 ترم 162\n\nالتحضير : يوميا بداية الكلاس ينادي بالأسماء ، لو هو يعرفك انك ملتزم وجيته بعذر شفهي إنك تأخرت ولا غبت بيقبله منك ، حبيب مع الطلاب\nطريقة الشرح : سلايدات ، الصدق الدكتور ما كان متمكن من ال205 فترة طويلة جدا ما درسها قبل 162 ، فلا تعتمد على الشرح ابدا ، تدرس بنفسك\nالكويزات : سهل الى وسط ، اذا ذاكرت من الكتاب وحليت بعض أسئلته بتحلها وأنت مغمض ، لا تخليها تضيع عليك أبد\nالمياجر: كومن مع دفوعة وقتها ، أشوفها وسط الى حد كبير لا سهل ولا صعب ، أفرج المياجر كان نازل جدا جدا فجانا الفاينل معتدل\nالصوت: هادي ، مسموع لكن لو تجلس آخر شي بتلقى نفسك راح تركيزك بسهولة\nإضافات : حاول تكون علاقتك مع الدكتور جيدة وخله يعرفك، يحترم ويراعي الناس الجادة معه أكثر من اللعّابة وبتلقى فرق التعامل واضح ، خلك مستقيم معه تمشي أمورك زي العسل.\nالكويزات حقته أعيد وأكرر بتلقاها بأسئلة الكتاب ، ذاكر من الكتاب نفسه وليس السلايدات وبعدين خذ لك فرة عالأسئلة وبتبدع فيها بالراحة\nالتصحيح معقول يعطيك حقك غالبا ، صار لي موقف بميجر 1 عطاني 0 بالسؤال عالفاينل أنسر لأنه غلط ، ما ألومه كثير لأن السؤال يا صح يا غلط ما فيه ذيك الخطوات اللي يمديه يعطيك درجات عليها\nعموما لا تعتقد انه يسلك بالتصحيح.\nتعامله اعيد وأكرر حبيب مع الطلاب ويبتسم كثير.\nخلاصة الموضوع أنصح فيه اذا : بتقضيها سلف ستدي ما راح تعتمد عالدكتور أبد + بتجي بدري عشان ترتاح من التأخير والقلق\n\nموفقين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493648-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-omar-al-turki/98636/12", "user": "MKD", "ts": 1528065403000, "tid": 98636, "pn": 12}}]}', 1528065403000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-amrfa-ise205', 'stk-amrfa', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f98640", "n": "Dr. Salih Duffuaa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE205 term 122\n\nالتحضير :بداية كل كلاس\nطريقة الشرح : حلوة\nالكويزات : مدري ايش نظامه بالضبط بداية الترم الين الميجر الاول كوز واحد بعد الميجر الاول كل يوم اثنين كوز !\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: B\nالصوت: واضح و مسموع و في كل جملة لازم يدخل كلمة بالعربي XD\n\nانصح فيه 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1218360-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-salih-duffuaa/98640/13", "user": "amrfa", "ts": 1367528775000, "tid": 98640, "pn": 13}}]}', 1367528775000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5535-ise205', 'stk-user5535', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f98640", "n": "Dr. Salih Duffuaa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 205\n\nTerm 141\n\nالتحضير : يوميا في بداية الكلاس ، ينادي اسمك و إذا جيت بعد الكلاس فأنت ليت\n\nطريقة الشرح : مرات من الكتاب و مرات من السلايدات ، و في بداية شبتر ٦ قام يشرح بالكلام فقط ، الرجل متمكن من المادة لدرجة موب طبيعية ، شرحه بطل جدا جدا جدا\n\nالكويزات : أول كويز كان معلمنا الوقت و كنا مستعدين ، اللي بعدها غير وضعه ، صار يدخل الكلاس و يقول يلا يا شباب كويز ، طبعا ما ادري وش فيه قلب علينا كان حبيب\n\nالمياجر: كومون\n\nالفاينلات : كومون\n\nالقريد النهائي: A+\n\nالصوت: واضح جدا\n\nإضافات :\n\n- لا تضيع الهلب سشن حقته\n- يثق فيك ، اذا جا دكتور بداله لا تحضّر نفسك و تمشي ، ترا غير موقفه من الكلاس بسبب ذي الحركة\n- أنا تخصصي كنترول ، لكن لو اني اندستريال ما اعتقد اني بأنزل اي كورس إلا معه لو كان موجود", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1421750-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-salih-duffuaa/98640/16", "user": "user5535", "ts": 1422040700000, "tid": 98640, "pn": 16}}]}', 1422040700000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sabfas-ise205', 'stk-sabfas', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f98640", "n": "Dr. Salih Duffuaa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 205 - Term 151\nالدكتور يصلح للطلاب المجتهدين فقط فقط… شرحه في الغالب موجه لهم , وشرحه بالغالب proof للمعادلات الموجودة في الكتاب ومن وين جت ومن هالكلام… راح يلحس مخك لمدة 20 دقيقة بس عشان يسوي prove.\n\nالدكتور تحضيره يومي ومتشدد من هالناحية بشكل كبير, لا من ناحية تأخير ولا من ناحية تفهّم للأحوال… يعني لو تغيب بسبب ظرف وتكلمه بعد ذلك, نسبة كبيرة ماراح يتفهّم حالك.\n\nالمياجر سهلة ممتنعة… إذا ماذاكرت زين او ذاكرت لكن ماكنت فاهم المنهج, فالله يعينك 😃\n\nأنصح فيه للي بيشد حيله ويشارك معه أثناء الكلاس ويكتب كلامه فقط فقط…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1440875-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-salih-duffuaa/98640/18", "user": "sabfas", "ts": 1454054845000, "tid": 98640, "pn": 18}}]}', 1454054845000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fahad_2012-ise205', 'stk-fahad_2012', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f98640", "n": "Dr. Salih Duffuaa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 142\nISE 205\n\nالتحضير : يومياً ويهتم بالحضور\n\nطريقة الشرح : يفتح السلايدات ويشرحها ويكتب عالسبورة ويهتم بفهم الطلاب , شرحه واضح واللي يكتبه عالسبوره مهم\n\nالكويزات : متوسطة الصعوبة\n\nالمياجر: متوسطة الصعوبة , راجع اسئلة الكتاب كثير منها تجي\n\nالفاينلات : نفس المياجر\n\nالقريد النهائي: A\n\nالصوت: واضح\n\nإضافات :\nالدكتور صالح من اقدم دكاترة القسم ودرس بنفسه بعض الدكاترة الموجودين بالاضافة الى المدير خالد السلطان\nالدكتور اخلاقه عاليه وانصح فيه في مواد التخصص كلها\nالدكتور يحفظ اسماء الطلاب اللي يشاركون معه\nما انصحك انك تجلس ب أول صف والسبب بتعرفه اذا اخذت معه 😛", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1450438-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-salih-duffuaa/98640/20", "user": "Fahad_2012", "ts": 1464240055000, "tid": 98640, "pn": 20}}]}', 1464240055000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ak-95-ise205', 'stk-ak-95', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f98640", "n": "Dr. Salih Duffuaa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE-205 term 152\n\nالتحضير :\nبداية كل كلاس، ينادي على الأسماء، ويدقق جدًا على التأخير\n\nطريقة الشرح :\nالدكتور ماشاء الله مختم المادة 👍، عنده سلايدات خاصة يشرح منها، ثم يشرح بالتفصيل على السبورة، ويحل مسائل ، يمكن ما عنده طريقة معينة متسلسلة في الشرح، لكن المهم إنك راح تفهم في النهاية 👍\nوأهم نقطتين لازم كل واحد بياخذ مع الدكتور يراعيهم ، وأشوف إنهم هم اللي يفرقوا بين فهم الطلاب ودرجاتهم في المياجر :\n1- الدكتور بيسوي في كل أسبوع هيلب سيشن، حاول ما تضيعهم أبدًا ، يراجع بشكل سريع ويركز على أهم النقاط ويحل المسائل المهمة، يوفر عليك وقت كثير في الدراسة لحالك 😏\n2- بعد نهاية كل شابتر، الدكتور يكتب على السبورة مثل ملخص أو خريطة ذهنية لدروس الشابتر، هاذي مهمة جدا جدا لأن الدروس في الشابتر الواحد كثيرة ومتشابهة أحيانًا ، بالملخص هاذي تقدر تعرف إيش المطلوب بالضبط، وإيش أهم الفروقات، ويعطي بعض الأمثلة، ويفضل طبعًأ بعدين إنك تسوي ملخص آخر أكثر تفصيلًا.\n\nالكويزات :\nمتوسطة تميل للصعوبة ، كان يعطي سؤالين من عدة فقرات، سؤال ينحل 👏 وسؤال تفحط فيه 🤪\n\nالمياجر ، الفاينلات :\nكومون ، مستواهم متوسط ، وتصحيح الدكتور عادي\n\nالقريد النهائي:\nA\n\nالصوت:\nواضح واللغة مفهومة والأكسنت ممتاز\n\nإضافات :\nالدكتور في الشرح وإيصال الفكرة ممتاز، أخلاق ويهتم فهم الطلاب ، قد يكون أحيانًا مزاجي ويزبد :slightly_smiling_face:، يقدر الطلاب المشاركين ويعطي بونص، ويحفظ الأسماء بسرعة ، ممكن أكبر سلبية اللي هي القريد ، سياسة الدكتور شوي صعبة ، الأغلبية الساحقة من الطلاب بين ال c و c+ ، ثم قلة قليلة بين b و b+ ، وطالب واحد يكون A أو A+\nلكني ما أعرف بين الدكاترة اللي يدرسون هاذي المادة واحد يدف في القريدات، بالتالي مع د. دفوعة عالأقل ستخرج بفهم ممتاز للمادة، ونصائح مهمة في الحياة والتخصص", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1454549-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-salih-duffuaa/98640/21", "user": "AK-95", "ts": 1469791214000, "tid": 98640, "pn": 21}}]}', 1469791214000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10932-ise205', 'stk-user10932', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f98640", "n": "Dr. Salih Duffuaa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 181 ، ISE205\nالتحضير : غالبا اول خمس دقايق من الكلاس يبدأ التحضير ، ومايحب ان الواحد يتأخر .\nطريقة الشرح : شريح درجه اولى ماشاء الله ، ويشرح من السلايدات ، طبعا يعقب على كل سلايد واذا كان فيه اثبات رياضي يثبته عالسبورة ( يحب الماث والاثباتات بشكل عجيب ويحببك فيها الصراحة ) ، وعنده بونص للي يشارك معه ويجاوب على اسئلته ، وانت وشطارتك ، كل ماجاوبت وشاركت يعطيك بونص .\nالكويزات : كويزاته غالبا بوب كويزز ( كويز مفاجئ ) ، لكن تقدر تتنبأ ان الكلاس الجاي بيكون فيه كويز او لا ، يا تكونون توكم مخلصين تشابتر او احياناً يلمح هو بنفسه .\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: +++++++A\nالصوت: واضح وتسمعه زين لو انت بآخر الكلاس ، والآكسنت الامريكي ضابط على لسانه والأجمل اذا تكلم بلهجة سودانية خفيفة وحلوة جدا .\nإضافات : البروفيسور صالح عثمان دفوعه ، حرفياً افضل دكتور مر علي في الجامعة ، سبحان الله طيبة قلبه وروحه المرحه تخليه يدخل قلبك غصب ، يقدر جدا اللي يجلسون قدام عنده ويحفظ اساميهم ودايم ينكت معهم ويمازحهم ( محدثكم واحد منهم 😆 ) ، الله يوفقه ويحفظه وين مايروح ، واذا تبغى نصائح عن التخصص او المواد او حتى شخصيه ، الانسان هذا سبحان الله موسوعه من العلم والحكم ، الله يبارك له ويرزقه طولة العمر على طاعته .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507634-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-salih-duffuaa/98640/23", "user": "user10932", "ts": 1553216673000, "tid": 98640, "pn": 23}}]}', 1553216673000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bader_alqahtani-ise205', 'stk-bader_alqahtani', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f98640", "n": "Dr. Salih Duffuaa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE205-191\nالتحضير: يحضر اول ٥ دقايق و شديد فيه اذا جيت متاخر يحطك ليت و الغياب يخصم عليه درجة و الليت ٠.٥ الدكتور يعطي بونص درجة للي م يغيب او الغياب عنده من ٦ درجات من ٥ اذا عندك غياب واحد عطاك 5/5 اذا ليت عطاك 5.5 من 5 ولا غياب 6 من 5\n\nالشرح :شرحه عادي يعطي امثله و يشرح من السلايدات م يحل مسائل كثير لكن احيانا يكتب سؤال على الصبورة و يقول لطلاب يحلون و يدور عليهم يعني لو مركز معه بتفهم الدرس بنسبه ٦٠٪؜ و يكون الشغل الباقي اخف عليك بس لازم تقرا الكتاب و تحل اسألته ،سلايداته م تكفي صراحة كلها رؤوس اقلام .\nالتصحيح:يعطيك حقك بالضبط بس شديد لو نقصت خطوة خصم و اذا زودت خطوة خصم حاول تكتب كل شي و توضح عشان يشوف انت فاهم م عنده بارشل كردت يعني لو حليت حل غلط يعطيك ٠ على حلك لو من البداية غلط.\n\nالتعامل:صراحة اشوف تعامله شديد و دايم يعارض الطلاب و ما اذكر كلمناه على شي و وافق اذكر القريدر كان تصحيحه سيء و كلمناه عشان الشي ذا و لا اهتم .\n\nالاختبارات: الكوزات عليها وزن كبير صراحة تقريبا ١٥٪؜ و عددهم ٦ طول الترم م يحذف شي و نظامها بوب كوز بس صراحة مستواها مو سهل و يبيلك تكون مذاكر حتى بتلاحظ ان الافرج حق كوزاته مازل و الدكتور يركز على مسائل الكتاب عليك فيها . طبعا هو دايما يكون الكوردنيتر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521999-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-salih-duffuaa/98640/24", "user": "Bader_Alqahtani", "ts": 1589340671000, "tid": 98640, "pn": 24}}]}', 1589340671000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11658-ise205', 'stk-user11658', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f98640", "n": "Dr. Salih Duffuaa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 205 TERM 192\n\nالتحضير:\nيحضر يوميا وع كلامه يعطي بونص للي مايغيب ولا كلاس في نهاية الترم.\n\nطريقة الشرح:\nعنده سلايدات خاصه فيه ياخذ منها روس اقلام ويسهب في الشرح من عنده بعض الاحيان يحل مسايل بس مو كثير مره ويتقبل الاسألة لكن بعض الاحيان يضيعك في الشرح يتشعب في مواضيع متقدمه وينسى من لب الدرس. لكن ككل شرحه مقبول الصراحة ويجتهد انه يوصلك معلومه ويفيدك.\n\nالكويزات:\nطبعا نظام الكويزات بوب كويز(مفاجىء) ولكن أنت تقدر تتنبأ بموعد الكويز أول ماتخلصون الشابتر فالكلاس الي بعده غالبا بيكون كويز وبعض الاحيان بيلمح لكم. بالنسبة لمستواها فالحقيقه انها مائلة الصعوبة ولازم تكون محضر لها صح عشان ما تتجحفل. أنا أخذتها في ترم الكورونا فقبل الاونلاين اخذنا كويزين والثاني كان يوم التعليق بالزبط وبعد ماقلب الوضع للاونلاين صارت الكويزات كلها اونلاين وكان الوضع دماااااااااااار حرفيا مهما تذاكر يصعب لك القريد في الكويزات وكلها هذا بحجة منع الغش.أذكر في واحد من الكويزات الاونلاين كان الافرج 8/20 :zipper_mouth_face: :zipper_mouth_face:.\n\nالمياجر:\nكومن\nالفاينالات:\nكومن وكانت اونلاين وماعندي خلفيه عنها لأني اخذت الماده NP\n\nالقريد النهائي:\nC\n\nإضافات :\nالدكتور الحقيقه مايقصر والله وده ينفع الطلاب ولكن عامل السن يأثر ع الواحد الركتور ممكن زمان كان افضل من الان بسبب الشباب والنشاط لكن الحين الدكتور خلاص كبير في السن ولكل عمر وضعه الخاص. لا أنصح نهائيا بأخذ كورس معه والوضع اونلاين أولا فالشرح يكون لك عليه بسبب قلة خبرة الدكتور بالتقنية ولا ينلام صراحة يعني اكثر من اربعين سنة يشرح ع صبورة والحين ع التيمز والبلاكبورد ففيه فرق كبير فلا انصح نهائيا. تعامله شوي مو متعاون مع الطلاب في مسايل تأجيل الكويزات ومواعيدها مع الهوموورك + وضعه في الاونلاين شوي معقد يعني أسألته في الكويزات مرررره صعبه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525323-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-salih-duffuaa/98640/26", "user": "user11658", "ts": 1599080658000, "tid": 98640, "pn": 26}}]}', 1599080658000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8581-ise205', 'stk-user8581', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f98641", "n": "Dr. S. Selim", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ise 205 - term 142\nالتحضير : اول اسبوعين في بداية الكلاس لكن اتوقع لأن الطلاب كانوا دايما يتأخرون قام يحضر نهاية الكلاس ونوعا ما متساهل من ناحية التأخير لكن تمصخها\n\nطريقة الشرح : من السلايدات ويستخدم السبورة لتوضيح بعض الأفكار والاجابة على اسئلة الطلاب شرحه جيد لكن فيه نقطة ماعجبتني فيه وهي انه يعطي اسئلة الطلاب اكثر من حقها يعني احيانا يضيع كلاس كامل عشان يجاوب اسئلة الطلاب و الي يقهر في طلاب يعيدون نفس السؤال الكلاس الي بعده فالنتيجة نوعا ما يكون متأخر عن بقية السكاشن وهو هذا السمستر كانت المياجر مع دفوعة ونضطر ناخذ ميك اب كلاس عشان يعوض تأخيره .\n\nالكويزات : مافيه للأسف\nالهوموركات : ماقال لنا كم عليها لكن هي والحضور عليهم تقريبا 25 % فلاتضيع اي هومورك + الهوموركات اذا حليتها اعتبر نفسك فهمت الشابتر لأنها سهلة نوعا ما لكن فيها افكار وتركات يمكن تجيك في المياجر …\n\nالمياجر & الفاينل : الميجر الاول د. دفوعة كتبه وكان متوسط نوعا ما الثاني كتبه د. سليم والافرج كان داج بقوة لكن مياجره تبين الي فاهم من الي حافظ فحاول تركز معاه في الكلاس لأنه احيانا يعطي بعض الملاحظات المهمة او الاخطاء الي دايما يسونها الطلاب + بعد كل سكشن حاول تحل 4 او 5 اسئلة من الكتاب وراح تستفيد لأن بعض اسئلة الميجر والفاينل كانت من الكتاب اللهم فيه تغيير بسيط في صياغة السؤال\n\nالقريد النهائي**:** كأخلاق وتعاون a+ لكن كشرح ماعجبتني طريقته مع انه مخلص يشرح بذمة واشوف الشباب ماشين معاه لكن الصراحة اشوفه عادي c\nالصوت : جيد والاكسنت واضح …\n\nإضافات :\n- لو مايعطي اسئلة الطلاب اكثر من حقها يكون افضل لأن كثرة الاسئلة تشتت الطالب + يضيع الكلاس ويكون الشرح ملخبط … وعشان ما اظلمه الدكتور اكثر من مرة وضح اهمية هذا الكورس خصوصا لطلاب الاندستريال فمن حرصه على الطلاب يعيد شرح بعض النقاط اكثر من مرة .\n- للأسف يتأخر في تسليم القريدات ( الى الان مانزلت تقريبا اسبوع وشوي )\n- الدكتور فاهم و خبرة و ما شاء الله عليه موسوعة في عدة اشياء مب بس تخصصه .\n- في المياجر والفاينل يسمح بالاسئلة فنصيحة اسئله راح تستفيد كثير .\n\" اذا كنت اندستريال و بتركز معاه في الكلاس ومستواك ممتاز نزل معاه فراح تستفيد اما اذا كنت من تخصص ثاني فما انصحك \"", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1422978-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-s-selim/98641/14", "user": "user8581", "ts": 1437934846000, "tid": 98641, "pn": 14}}]}', 1437934846000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bukhari.m.i-ise205', 'stk-bukhari.m.i', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f98655", "n": "Dr. M Dhurgham", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ise205\nالتحضير : الدكتور ما يحضر إلا نادرا لكن يعطي كويزات لمن يشوف الغياب زايد\nطريقة الشرح : حلو ومفيد بعض الاحيان يلخبط\nالكويزات : الكويزات سهلة ويعطي كويزات كثير عشان يرفع الكلاس وورك\nالفاينلات والمياجر : كومون\nالقريد النهائي: B\nالصوت: جيد\nإضافات : الدكتور جدا متواضع وتعامله محترم وشرحه حلو ابدا ماندمت اني نزلت معاه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p750698-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-dhurgham/98655/3", "user": "bukhari.M.I", "ts": 1293169053000, "tid": 98655, "pn": 3}}]}', 1293169053000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_3abed1-ise205', 'stk-abu_3abed1', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f98655", "n": "Dr. M Dhurgham", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE 205 - Term 182\n\nالتحضير : ينادي الاسماء بشكل يومي قبل نهاية الكلاس ، قليلة الايام اللي ما يحضر فيها.\n\nالشرح : صراحه حيرني معاه احيانا يبدع ابداع لا نظير له في الشرح واحيانا يلخبط شوي ولكن بالمجمل الرجل فاهم المادة وفاهم التخصص مضبوووط.\nافضل شي فيه انه كثير الكتابة في السبورة ويجيب امثلة كثير من عنده واغلبها من الواقع التطبيقي للتخصص واذا خلص الشرح في السبورة يفتح السلايدات ويراجع نفس اللي شرحه في السبورة عشان اذا رجعت البيت تعرف وين وصلنا في السلايدات.\n\nالكويزات: سهلة غالبا وهو يقول دايما انا الكويزات عندي بمثابة الهدية في جيب الطالب.\nالمياجر: كومون\nالفاينلات: كومون\n\nالتصحيح: اشوف تصحيحه حقاني واذا حسك فاهم يساعدك شوي .\n\nالقريد النهائي: يستاهل B+\n\nالصوت : واضح\n\nإضافات:\n- الدكتور متقبل للاسئلة و يتمنى اي احد يساله.\n- يزعجه جدا استخدام الجوال.\n- اخلاقه عاليه جدا ويعاملك كشخص في عمره يعني مافي دكتور وطالب.\n- عيبه احيانا يضيع بالشرح مش لانه مش فاهم ولكن بسبب انه ما يرتب شرحه احيانا.\n- واجباته قليل تقريبا كان عندنا واجبين او ثلاثة طول السمستر.\n\nاخيرا: الكتاب جدا مغني عن دكتور المادة ومن افضل الكتب اللي مرت علي بحيث انك اذا قريتها تفهم الكونسبت، فلا تشيل هم الدكتور.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509674-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-dhurgham/98655/33", "user": "Abu_3abed1", "ts": 1557758580000, "tid": 98655, "pn": 33}}]}', 1557758580000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abinmua-ise205', 'stk-abinmua', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f147064", "n": "Dr. Abdul Qadar Kara", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سمستر : 201 - ise205\nالتحضير : مايحضر بترم الاونلاين\nطريقة الشرح : سلايدات ويالله تفهم اكسنت صعب جدا تفهمه\nالكويزات : بداية بعض الكلاسات يسوي كويز سهل\nالتيستات : ٦ تيستات والافرج تحت النص ، واغلبها صعب وبعضها متوسط وجاب واحد سهل يبي يرفع الافرج\nالهوموركات : كثيرة ودقيق جداً بالتصحيح وركز عليها التيست يكون قريب من افكارها\nالقريد النهائي : F+ ازبن منه الا اذا انحديت شد حيلك سلف ستدي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526913-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdul-qadar-kara/147064/20", "user": "AbinMua", "ts": 1607055512000, "tid": 147064, "pn": 20}}]}', 1607055512000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-ise205', 'stk-guest', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f147064", "n": "Dr. Abdul Qadar Kara", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ise205 ترم 201\nالتحضير:ما يحضر في الاونلاين\nالشرح: خصوصا في البداية اول اسبوعين كان ما يمديك تسمع شي بعدين صلح المايك، و رغم ذلك برضه الاكسنت صعب و يتكلم بسرعة بالنسبة لي اشوف محاضراته مملة.\n\nالواجبات: يعطيك واجبات طويلة جدا جدا و صعبة حلها ياخذ وقت\n\nالكويزات: متوسطة\n\nالاختبارات: عطانى تقريبا ٦ اختبارات عليه ٦٩٪ اشوفها كلها صعبة الآفرج دايم نازل\nالفاينال كان اورال و سفل فيني تسفيل ما يسوي ماني لوحدي الأغلب سفل فيهم\n\nالتقييم النهائي: اعطيه F- ودي اني ما نزلت عنده صراحة اسوء شخص درسني في حياتي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527294-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdul-qadar-kara/147064/21", "user": "Guest", "ts": 1608970299000, "tid": 147064, "pn": 21}}, {"id": "stk-dr-f176914", "n": "Dr. Ahmed Attia", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "😔أخذت ISE 205 معاه في Term 201:\n\nالتحضير:\nكان ياخذ التحضير من زوم بس في الاخير ما حسيت انه نقص شي\n\nطريقة الشرح:\nيشرح على البوربوينت وبلهجة انقليزية مصرية، شرحه متواضع يعني ما اضمن لك تفهم الكونسبت ١٠٠٪؜ اذا اعتمدت عليه، ولكن يكفي تراجع الريكوردنق عشان تجيب درجة كويسه في اختباراته.\n\nالـtests:\nعطونا ٦ اختبارات كل واحد 10% وبالنسبة لأبو عطية فكان اغلب اسئلته يجيبها من الكتاب نصًا.\n\nالمد:\nوزعه على اختبارين conceptual واحد مع test3 وواحد مع test4\n\nالفاينل:\nاورال (شفهي) وكان على الكونسبت\n\nالقريد النهائي:\nاخخخخ يبو عطية ولكن اضطر اقول B+\n\nإضافات:\nصراحة من افضل الدكاترة الي مروا علي من ناحية التعامل والاخلاق ومراعاة الطلاب خصوصًا في هذا الترم اللعين، الدكتور عسسسسسسسل بشكل زيادة عن الحد المسموح، لدرجة انتزعنا لقب فخر العرب من ابو صلاح واعطيناها لأبو عطية، ولكن للأسف هذا الشي رجع علينا بشكل سلبي، الدكتور اختباراته ماهي صعبة مرة زي ما قلت كان يجيبها من الكتاب وكان متساهل من ناحية المراقبة وكذا وما ابغى احط شي في ذمتي ولكن كان الافرج اغلب الاحيان مرتفع وألي ادى الى ان القريدات كذلك ترتفع 😔 يعني تخيلوا المادة صارت كأنها ستاندرد الـA+ من 95 والـA من 90 وهكذا.\n\nختامًا الدكتور يراعي الطلاب بشكل كبير ما عنده مشكلة يأجل الاختبارات ويسوي تصويت للوقت المناسب للجميع وكذا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527710-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-attia/176914/7", "user": "Guest", "ts": 1610158806000, "tid": 176914, "pn": 7}}]}', 1608970299000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-feras-mtn-ise205', 'stk-feras-mtn', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f172118", "n": "Dr. Hany Osman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE205-Term191\n\nالتحضير : كلاسات يحضر وكلاسات مايحضر … واذا حضرت اخر ٥ دقايق من الكلاس بيحضرك واذا ماكان رايق بيحطك ليت\nطريقة الشرح :\nكورس 205 ماكان متمكن فيه كثيير للامانه لكن تحسه يحاول قد مايقدر\nالكويزات :\n٥ كويزات وياخذ احسن ٤ … وياتكون متوسطة مائلة للصعوبة ويامتوسطة مائلة للسهولة\nالمياجر: كومون لكن تصحيحه اشوف حقاني تحط اجابة بالخطوات والنواتج غلط مايعطيك درجات عالحل (يا ابيض يا اسود)\nالقريد النهائي: +C\nالصوت: واضح\nإضافات :\nيعطي بونص في الكلاس للي يحل سؤال كان يعطينا اياه في الكلاس واول واحد يسلمه ياخذ درجة من 100 … بس كان والله ارجل دكتور في 205 في ترمنا لانه الدكتور دفوعة استقعد لطلابه وماوافق يرسلهم الفورميلا شيت قبل المياجر وكان يقلهم ذاكرو كل حاجة حتى اللي ما انشرحت ومالها داعي … لكن الدكتور هاني معانا عطانا العلم في ايش اللي نذاكره ومانذاكره وارسلنا الفورميلا شيت فباختصار كان متعاون معانا كثيير والله وحتى هومووركاته كانت كل طالبين مع بعض", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1519212-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hany-osman/172118/7", "user": "Feras-MTN", "ts": 1579487347000, "tid": 172118, "pn": 7}}]}', 1579487347000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dex-ise205', 'stk-dex', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f176914", "n": "Dr. Ahmed Attia", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE205- Term211\nالتحضير:\nورقة تحضير تمر على الطلاب بنص المحاضرة … ما يسجل تأخير\nطريقة الشرح:\nيشرح سلايدات الكتاب ويحل الاسئلة الي فيها على السبوره بالتفصيل\nالكويزات:\nمب صعبه ولا سهله وسط … يعطيك حقك وحبه زياده … ياخذ ٥ من ٧\nالميجر الاول:\nكومن … الميجر الاول من ٢٠ وفيه اسهل تشابترين (٢،٦) حاول ما تضيع درجات فيه\nالميجر الثاني:\nكومن … اصعب بكثييير من الاول\nالفاينل:\nكومن … ميزته مب شامل جميع التشباتر\nالقريد النهائي:\nB\nالصوت:\nواضح لكنه هادي ودرجة صوت وحده من بدايه المحاضرة للنهاية فكلاساته تجيب النوم\nإضافات:\nالدكتور حبيب ومتساعد ودايم اذا طلبوا منه الطلاب يأجل واجب او كويز ما يرفض … تعامله راقي جداً", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533356-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-attia/176914/11", "user": "Dex", "ts": 1641580551000, "tid": 176914, "pn": 11}}]}', 1641580551000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12137-ise205', 'stk-user12137', 'ISE 205', 'doc', '{"docs": [{"id": "stk-dr-f176914", "n": "Dr. Ahmed Attia", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE205- Term231\nالتحضير:\nورقة تحضير تمر على الطلاب بنص المحاضرة…ما يسجل تأخير وفقط 15 مرة طول السمستر, وغالبا يطلعكم بدري في معظم الكلاسات\nطريقة الشرح:\nيشرح سلايدات الكتاب ويحل الاسئلة الي فيها على السبوره بالتفصيل, السبورة لا تفرطوا بها صوروها وذاكروا منها جدا مرتبة وأسهل للفهم لما تحل, بس المشكلة الي لاحظتها أنه يركز على الحل بشكل كبير لدرجة أن الكونسبت قليل يشرحه, لا تفهمني غلط مو معناه ما يشرح كونسبت, بالعكس كل يعطي أمثلة على الفكرة من الحياة الواقعية لكن ما حسيت كافي\nالكويزات:\nمو صعبة ولا سهلة وسط … يعطيك حقك وحبتين زيادة … ياخذ ٥ كويزات من أصل ٧ … حتى لو تغلط بالحسابات اذا فاهم الفكرة وحليت ورويته التفاصيل بيضبطك\nالميجر الاول:\nكومن … الميجر الاول (٢،٦)وهو الاسهل المفروض بس أحس كنت مستصعب تشابتر 2 فأنكبت وجبت على الأفرج 31-32 من 40\nالميجر الثاني:\nكومن … (3,4) اصعب من الاول أيضا جبت على الآفرج 28 من 40\nالفاينل:\nكومن …(4,5,7) ميزته مب شامل جميع التشباتر ويعتبر أسهل من الميجر الثاني (ما أعلنوا عن الآفرج) وأنا جبت 33 من 40\nالقريد النهائي:\nA\nالصوت:\nواضح جدا وعالي وليس بهادئ ولكن “الرتم” ثابت فشوي ما تركز أحيان\nإضافات:\n-الدكتور حبيب ومتساعد ودايم اذا طلبوا منه الطلاب يأجل واجب او كويز ما يرفض … تعامله راقي جداً وبشوش ويقدم هيلب سشنات\n-الهوموركات تبعه حلوة ومفيدة فحاول تحلهم بنفسك غالبا كلها فل بيعطيكم\n-الدكتور أشوفه خيار ممتاز للمادة\n-أنا رغم أن كل شيء آفرج عندي تقريبا وغايب 3 مرات (وزنها ثقيل بالMW) الا أني حصلت على B+ عدا الهووموركات والكويزز فأظن توزيع القريدات عندهم مرتفع, الظاهر الA+ من 87 وفوق كانت", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537218-ise205", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-attia/176914/12", "user": "user12137", "ts": 1704978225000, "tid": 176914, "pn": 12}}]}', 1704978225000, 1794826863, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
